/*
 * bfont.h: 4-bit anti-aliased bitmap fonts generated by tools/gen_font.py
 * (Albert Sans, the face the proposal's mock-up uses). Glyph rows are packed
 * 2 px/byte, high nibble = left pixel, 0 = no ink .. 15 = full ink. Codes
 * 0x7F and 0x80 are the degree sign and the middle dot ("\x7f", "\x80").
 */
#pragma once

#include <stdint.h>

typedef struct {
    uint16_t code;
    uint16_t adv;          /* pen advance, px */
    uint16_t w, h;         /* bitmap size */
    int16_t  xoff, yoff;   /* bitmap offset from the pen origin (top = ascender line) */
    uint32_t off;          /* byte offset into bits */
} bglyph_t;

typedef struct {
    const bglyph_t *glyphs;
    uint16_t        count;
    uint16_t        line_h;   /* ascent + descent */
    uint16_t        ascent;
    const uint8_t  *bits;
} bfont_t;

extern const bfont_t ui30, ui34, ui46, ui72, ui96, num180, num270, clock214, icon34, icon46, icon170;
